(() => {
  const c = document.querySelector('[data-chat-scroll="true"]');
  if (!c) throw new Error('the transcript is not on screen');
  const rows = [...c.querySelectorAll('[data-message-id]')];
  if (rows.length < 4)
    throw new Error('the transcript still holds only the tail page: ' + rows.length + ' rows');
  if (c.scrollHeight <= c.clientHeight + 40)
    throw new Error('the transcript does not fill its viewport (' + c.scrollHeight + ' in ' + c.clientHeight + '), so it has no scrollbar and no way to page up');
  const frame = c.parentElement;
  const thumb = [...(frame ? frame.querySelectorAll('div') : [])]
    .find(node => /height: [1-9]/.test(node.getAttribute('style') || ''));
  if (!thumb) throw new Error('the floating scrollbar has no thumb');
  const box = c.getBoundingClientRect();
  const newest = rows[rows.length - 1].getBoundingClientRect();
  if (newest.bottom > box.bottom + 2)
    throw new Error('the view did not settle on the newest message: ' + Math.round(newest.bottom - box.bottom) + 'px below the fold');
  return 'filled: ' + rows.length + ' rows';
})()

(() => {
  const c = document.querySelector('[data-chat-scroll="true"]');
  if (!c) throw new Error('the transcript is not on screen');
  const rows = [...c.querySelectorAll('[data-message-id]')];
  if (rows.length < 2) throw new Error('the transcript holds ' + rows.length + ' rows, too few to tell the newest message from the tail');
  c.scrollTop = c.scrollHeight;
  const tail = c.getBoundingClientRect().bottom - rows[rows.length - 1].getBoundingClientRect().bottom;
  if (!(tail > 8)) throw new Error('the transcript reserves no tail below its newest message (' + Math.round(tail) + 'px), so no parked position can separate the two measures');
  window.__jumpCheck = { tail };
  c.scrollTop = c.scrollHeight - c.clientHeight - (tail - 18);
  return 'tail ' + Math.round(tail) + 'px';
})()

(() => {
  const c = document.querySelector('[data-chat-scroll="true"]');
  const rows = [...c.querySelectorAll('[data-message-id]')];
  const fold = c.getBoundingClientRect().bottom;
  const gap = rows[rows.length - 1].getBoundingClientRect().bottom - fold;
  const distance = c.scrollHeight - c.clientHeight - c.scrollTop;
  if (gap > 2)
    throw new Error('setup: the newest message is ' + Math.round(gap) + 'px below the fold, so this is not the "already in view" case');
  if (distance <= 240)
    throw new Error('setup: the content end is only ' + Math.round(distance) + 'px below the fold, short of the 240px that used to reveal the button (tail ' + Math.round(window.__jumpCheck.tail) + 'px)');
  const chip = [...document.querySelectorAll('button[aria-label]')]
    .find(b => /回到最新|jump to latest/i.test(b.getAttribute('aria-label') || ''));
  if (chip)
    throw new Error('the jump button is offered while the newest message ends ' + Math.round(-gap) + 'px inside the viewport (the content end is ' + Math.round(distance) + 'px below the fold)');
  return 'no chip: newest end ' + Math.round(-gap) + 'px inside, content end ' + Math.round(distance) + 'px below the fold';
})()

(() => {
  const c = document.querySelector('[data-chat-scroll="true"]');
  c.scrollTop = Math.max(0, c.scrollHeight - c.clientHeight - (window.__jumpCheck.tail + 400));
  return 'scrolled up';
})()

(() => {
  const c = document.querySelector('[data-chat-scroll="true"]');
  const rows = [...c.querySelectorAll('[data-message-id]')];
  const gap = rows[rows.length - 1].getBoundingClientRect().bottom - c.getBoundingClientRect().bottom;
  const chip = [...document.querySelectorAll('button[aria-label]')]
    .find(b => /回到最新|jump to latest/i.test(b.getAttribute('aria-label') || ''));
  if (!chip)
    throw new Error('the jump button never appears, even with the newest message ' + Math.round(gap) + 'px below the fold');
  return 'chip back with the newest message ' + Math.round(gap) + 'px below the fold';
})()
